                R(ref s, "K. Asogi and A. Shinn...<E049><E003 14><E025 2><E043>are the names of <E006>assassins<E005>.", "K. Asogi et A. Shinn...<E049><E003 14><E025 2><E043>sont les noms des <E006>assassins<E005>.");
                R(ref s, "No...", "Non...");
