            // [6] BB\script\output\_sce04_c301_0020_eng#6
            entryTranslators[@"BB\script\output\_sce04_c301_0020_eng#6"] = (s) => {
                R(ref s, "A. Shinn and her victim J. Wilson...", "A. Shinn et sa victime J. Wilson...");
