                R(ref s, "K. Asogi <E049><E003 8>and T. Gregson...", "K. Asogi <E049><E003 8>et T. Gregson...");
                R(ref s, "One assassin from each country<E049><E003 8> to kill a target residing in\r\nthe other.", "Un assassin originaire de chaque pays<E049><E003 8> chargé d'abattre une cible vivant\r\ndans l'autre.");
                R(ref s, "What exactly is the defence suggesting?", "Qu'insinue exactement la défense ?");
                R(ref s, "These two cases of murder, <E049><E003 8><E025 2>one that took place in Britain<E049><E003 8>\r\n<E025 3>and one in Japan...", "Ces deux affaires d'assassinat, <E049><E003 8><E025 2>l'une perpétrée en Grande-Bretagne<E049><E003 8>\r\n<E025 3>et l'autre au Japon...");
                R(ref s, "...were masterminded by a pair of individuals from each\r\ncountry <E049><E003 12><E025 1><E346>as a form of <E006>assassin exchange<E005>!", "...ont été orchestrées par deux individus issus de chaque\r\npays, <E049><E003 12><E025 1><E346>sous la forme d'un <E006>échange d'assassins<E005> !");
                R(ref s, "And the telegram the defence has acquired <E049><E003 15><E025 1><E164 1 8 1 2 5 1 1 1><E139 1><E006>is proof<E005> of this\r\ninternational ‘contract’ to kill!", "Et le télégramme obtenu par la défense <E049><E003 15><E025 1><E164 1 8 1 2 5 1 1 1><E139 1><E006>est la preuve<E005> de ce\r\n« contrat d'assassinat » international !");
                R(ref s, "Wha<E025 7>...<E049><E003 12><E025 1><E604><E145 112 16>WHAT?!", "Qu<E025 7>...<E049><E003 12><E025 1><E604><E145 112 16>QUOI ?!");
                R(ref s, "The telegram was found in your office, <E049><E003 10><E025 1><E335>Judge Jigoku!", "Ce télégramme a été retrouvé dans votre bureau, <E049><E003 10><E025 1><E335>juge Jigoku !");
                R(ref s, "In other words, <E049><E003 10>the mastermind in Japan...<E049><E003 15><E061 1><E025 1><E549 7 20 3 1><E131><E332>was you!", "En d'autres termes, <E049><E003 10>le commanditaire au Japon...<E049><E003 15><E061 1><E025 1><E549 7 20 3 1><E131><E332>c'était vous !");
                R(ref s, "Judge Jigoku...?<E049><E003 12>\r\n<E164 112 7 1 2 9 0 2 1><E139 112><E025 1>What's this all about?!", "Juge Jigoku... ?<E049><E003 12>\r\n<E164 112 7 1 2 9 0 2 1><E139 112><E025 1>Qu'est-ce que tout cela signifie ?!");
                R(ref s, "And you, <E049><E003 6>Kazuma...<E049><E003 10> <E145 1 21><E003 10><E025 3><E330>You lied.", "Et toi, <E049><E003 6>Kazuma...<E049><E003 10> <E145 1 21><E003 10><E025 3><E330>Tu as menti.");
                R(ref s, "During yesterday's proceedings, <E049><E003 8><E025 2>you acknowledged that\r\nyou'd accepted the assassination mission.", "Lors de l'audience d'hier, <E049><E003 8><E025 2>tu as reconnu avoir accepté\r\nla mission d'assassinat.");
                R(ref s, "But the mark <E049><E003 10><E025 3>wasn't Judge Jigoku at all.", "Mais la cible <E049><E003 10><E025 3>n'était nullement le juge Jigoku.");
                R(ref s, "It was ‘T. Gregson’, <E049><E003 15><E025 2>Detective Inspector of Scotland Yard...", "C'était « T. Gregson », <E049><E003 15><E025 2>inspecteur divisionnaire de Scotland Yard...");
                R(ref s, "...as shown by the name on the killing contract!", "...comme en témoigne le nom figurant sur ce contrat de mort !");
                R(ref s, "Very impressive, <E049><E003 8>Ryunosuke.", "Très impressionnant, <E049><E003 8>Ryunosuke.");
                R(ref s, "But actually, <E049><E003 9><E145 112 4><E118 112 1.21><E149 112 5 4><E003 15><E025 3><E238>I didn't lie.", "Mais en réalité, <E049><E003 9><E145 112 4><E118 112 1.21><E149 112 5 4><E003 15><E025 3><E238>je n'ai pas menti.");
