            // [7] BB\script\output\_sce04_c301_0020_eng#7
            entryTranslators[@"BB\script\output\_sce04_c301_0020_eng#7"] = (s) => {
                R(ref s, "The defence claims these four names indicate some sort<E145 61 7><E118 61 0.7>\r\nof international assassin exchange?", "La défense soutient que ces quatre noms relèveraient d'une sorte<E145 61 7><E118 61 0.7>\r\nd'échange d'assassins international ?");
                R(ref s, "I'm sure I speak for all present when I say<E049><E003 7> <E061 1><E145 61 10><E118 61 1.2><E003 8><E025 3>that the very\r\nidea seems utterly absurd.", "Je suis certain d'exprimer le sentiment de tous ici présent en disant<E049><E003 7> <E061 1><E145 61 10><E118 61 1.2><E003 8><E025 3>qu'une telle\r\nidée paraît absolument absurde.");
                R(ref s, "Well, <E049><E003 8>Mr Jigoku?<E049><E003 12>\r\n<E338><E025 2><E342>What do you have to say for yourself?", "Eh bien, <E049><E003 8>M. Jigoku ?<E049><E003 12>\r\n<E338><E025 2><E342>Qu'avez-vous à répondre à cela ?");
                R(ref s, "His silence <E049><E003 10><E164 1 71 1 2 1 0 1 1><E118 1 1.2><E139 1><E025 1>only goes to prove his guilt!", "Son silence <E049><E003 10><E164 1 71 1 2 1 0 1 1><E118 1 1.2><E139 1><E025 1>ne fait que démontrer sa culpabilité !");
                R(ref s, "There's another <E145 1 85>very important point that this new\r\ndevelopment brings to light.", "Il y a un autre <E145 1 85>point crucial que ce nouvel élément\r\nmet en lumière.");
                R(ref s, "There's now a distinct possibility <E049><E003 8><E025 3>that the scene of\r\nInspector Gregson's actual murder...", "Il existe désormais une forte probabilité <E049><E003 8><E025 3>que le lieu véritable\r\ndu meurtre de l'inspecteur Gregson...");
                R(ref s, "...was in the witness's cabin aboard the SS Grouse!", "...soit la cabine du témoin à bord du SS Grouse !");
                R(ref s, "Judge Jigoku, <E049><E003 10><E025 2>you have to testify now!<E049><E003 8>\r\n<E025 1><E145 1 7><E118 1 1.2><E003 10><E332>To refuse would put you in contempt of court!", "Juge Jigoku, <E049><E003 10><E025 2>vous devez témoigner sur-le-champ !<E049><E003 8>\r\n<E025 1><E145 1 7><E118 1 1.2><E003 10><E332>Un refus constituerait un outrage au tribunal !");
                R(ref s, "There's no need for quite such a vicious stare, <E003 4>young man!", "Il n'y a nul besoin de me foudroyer du regard ainsi, <E003 4>jeune homme !");
                R(ref s, "Very well, then.<E049><E003 12> As a parting gift to you all, <E049><E003 6>I'll tell you\r\neverything I know.", "Fort bien, dans ce cas.<E049><E003 12> En guise de cadeau d'adieu, <E049><E003 6>je vais vous dire\r\ntout ce que je sais.");
                R(ref s, "It seems this Japanese gentleman <E049><E003 8><E145 61 7><E118 61 0.7><E003 5><E025 2>has information that the\r\ncourt must hear.", "Il semble que ce dignitaire japonais <E049><E003 8><E145 61 7><E118 61 0.7><E003 5><E025 2>ait des informations dont\r\nle tribunal doit entendre la teneur.");
                R(ref s, "About the alleged ‘assassin exchange’ <E049><E003 8>and the events of\r\nthe night of the 31st October.", "Au sujet de ce prétendu « échange d'assassins » <E049><E003 8>et des événements\r\nde la nuit du 31 octobre.");
                R(ref s, "Present your formal testimony now.", "Présentez votre déposition officielle dès à présent.");
                R(ref s, "...As you wish, <E049><E003 10>My Lord.", "...Bien, <E049><E003 10>Votre Honneur.");
                return s;
            };

            // [8] BB\script\output\_sce04_c301_0020_eng#8
            entryTranslators[@"BB\script\output\_sce04_c301_0020_eng#8"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu assez de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît clairement <E049><E003 8><E025 2>que toute discussion supplémentaire sur cette affaire\r\nsera stérile.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Drake Van Peers, <E049><E003 8><E025 2>j'ose espérer que, bien qu'égaré...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "...vous avez néanmoins agi au nom de la justice.<E049><E003 12>\r\n<E025 3>Même s'il m'en coûte d'en arriver à cette conclusion...");
                R(ref s, "No!<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Wait, My Lord!", "Non !<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de ce tribunal, <E049><E003 6><E025 3>je déclare\r\npar la présente l'accusé, <E049><E003 6><E025 3>Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "L'affaire est entendue.<E049><E003 10>\r\n<E025 2>L'audience est levée !");
                return s;
            };

            // [9] BB\script\output\_sce04_c301_0030_eng#2
            entryTranslators[@"BB\script\output\_sce04_c301_0030_eng#2"] = (s) => {
                R(ref s, "– The Assassin Exchange –", "– L'échange d'assassins –");
                R(ref s, "It's true <E049><E003 6>that Kazuma Asogi was assigned the assassination\r\nmission one year ago now.", "Il est exact <E049><E003 6>que Kazuma Asogi s'est vu confier cette mission\r\nd'assassinat il y a un an de cela.");
                R(ref s, "The target was Inspector T. Gregson.<E049><E003 12>\r\n<E025 2>That was a condition of the British study tour.", "La cible était l'inspecteur T. Gregson.<E049><E003 12>\r\n<E025 2>C'était une condition préalable à son séjour d'études britannique.");
                R(ref s, "However...<E049><E003 10><E025 3>in the end something happened <E049><E003 8><E025 2>that meant the\r\nyoung man was unable to carry out his mission.", "Toutefois...<E049><E003 10><E025 3>un incident s'est finalement produit, <E049><E003 8><E025 2>empêchant\r\nce jeune homme d'accomplir sa besogne.");
                R(ref s, "On the evening in question, <E049><E003 8>a member of the crew was on\r\nduty outside my cabin at all times.", "Le soir en question, <E049><E003 8>un membre de l'équipage montait\r\nla garde en permanence devant ma cabine.");
                R(ref s, "If there'd been a shot fired, <E049><E003 6>the crewman would have\r\nheard it.<E049><E003 14> <E145 47 68><E118 47 1.3><E025 2><E045>So clearly I can't be involved.", "Si un coup de feu avait retenti, <E049><E003 6>ce matelot l'aurait\r\nforcément entendu.<E049><E003 14> <E145 47 68><E118 47 1.3><E025 2><E045>Je ne puis donc être mêlé à cela.");
                return s;
            };

            // [10] BB\script\output\_sce04_c301_0030_eng#3
            entryTranslators[@"BB\script\output\_sce04_c301_0030_eng#3"] = (s) => {
                R(ref s, "So you admit it, then?<E049><E003 10>\r\n<E025 2><E060 0 158 1 0>As this communication suggests...", "Vous l'admettez donc ?<E049><E003 10>\r\n<E025 2><E060 0 158 1 0>Comme le suggère ce message...");
                R(ref s, "...there really was an assassin exchange arrangement\r\nbetween Britain and Japan!", "...il existait bel et bien un accord d'échange d'assassins\r\nentre la Grande-Bretagne et le Japon !");
                R(ref s, "A political endeavour at the highest levels.<E049><E003 10>\r\n<E025 2>Not something I can discuss here.", "Une manœuvre politique au plus haut niveau de l'État.<E049><E003 10>\r\n<E025 2>Rien dont je puisse débattre ici.");
                R(ref s, "To use such a worthy practice as foreign study to coerce\r\nsomebody to commit murder...", "Se servir d'une pratique aussi noble qu'un voyage d'études pour contraindre\r\nquelqu'un à commettre un meurtre...");
                R(ref s, "It's the most appalling thing I've ever heard!", "C'est la chose la plus abjecte que j'aie jamais entendue !");
                R(ref s, "Appalling?<E049><E003 10>\r\n<E025 3><E145 47 81><E144 47><E239>Well, <E049><E003 8>it's easy to judge...", "Abjecte ?<E049><E003 10>\r\n<E025 3><E145 47 81><E144 47><E239>Voyons, <E049><E003 8>il est si facile de juger...");
                R(ref s, "Asogi had <E006>a reason<E005> for taking his sword to that British\r\ninspector, <E049><E003 4>you know.", "Asogi avait <E006>une raison<E005> de lever sa lame contre cet inspecteur\r\nbritannique, <E049><E003 4>vous savez.");
                R(ref s, "Which is why he accepted the mission in the first place.<E049><E003 15>\r\n<E145 47 82><E117 47 20><E003 8><E330>Isn't that right...<E049><E003 10>Counsel?", "Et c'est précisément pourquoi il a accepté cette mission au départ.<E049><E003 15>\r\n<E145 47 82><E117 47 20><E003 8><E330>N'est-ce pas... <E049><E003 10>Monsieur le Procureur ?");
                R(ref s, "Kazuma-sama...?", "Maître Kazuma... ?");
                R(ref s, "Judge Jigoku, <E049><E003 8>if you are the mastermind behind this\r\noperation in Japan...", "Juge Jigoku, <E049><E003 8>si vous êtes le commanditaire de cette\r\nopération au Japon...");
                R(ref s, "...then tell the court the identity of your counterpart in\r\nBritain!", "...alors révélez au tribunal l'identité de votre homologue\r\nen Grande-Bretagne !");
                R(ref s, "I'm not obliged to divulge that information.", "Je ne suis nullement tenu de divulguer cette information.");
                R(ref s, "As I said yesterday, <E049><E003 10><E025 3>I've killed nobody.", "Comme je l'ai affirmé hier, <E049><E003 10><E025 3>je n'ai tué personne.");
                R(ref s, "I freely admit that I accepted the mission, <E049><E003 6>but on the night\r\nthe plan was to be executed, <E049><E003 8><E025 3>I backed out.", "J'admets volontiers avoir accepté cette mission, <E049><E003 6>mais la nuit où\r\nle plan devait être exécuté, <E049><E003 8><E025 3>j'ai renoncé.");
                R(ref s, "In short, <E049><E003 8>this assassin exchange that the defence has\r\nidentified <E049><E003 8>is <E006>unrelated<E005> to the events of this case.", "Bref, <E049><E003 8>cet échange d'assassins mis en avant par la défense\r\nest <E006>sans aucun lien<E005> avec les faits qui nous occupent.");
                R(ref s, "The crucial point is this:", "Le point crucial est le suivant :");
                R(ref s, "Your police inspector can't have perished aboard that\r\nsteamship in Dunkirk.", "Votre inspecteur de police n'a pas pu périr à bord de ce\r\nnavire à vapeur à Dunkerque.");
                R(ref s, "Because if he'd been shot in the cabin, <E049><E003 6>it's inconceivable\r\nthat a member of the crew wouldn't have heard it.", "Car s'il avait été abattu dans la cabine, <E049><E003 6>il est impensable\r\nqu'aucun membre d'équipage ne l'ait entendu.");
                R(ref s, "Gregson was killed after returning to London.<E049><E003 10>\r\n<E025 3>In the room on Fresno Street.", "Gregson a été tué après son retour à Londres.<E049><E003 10>\r\n<E025 3>Dans cette chambre de Fresno Street.");
                R(ref s, "And the perpetrator of the crime<E049><E003 8> was the Reaper,<E049><E003 12> <E025 2><E346>Barok\r\nvan Zieks!", "Et l'auteur de ce crime<E049><E003 8> n'est autre que le Faucheur,<E049><E003 12> <E025 2><E346>Drake\r\nVan Peers !");
                R(ref s, "The prosecution's accusation<E049><E003 6> remains unchanged.", "L'accusation maintenue par le parquet<E049><E003 6> demeure inchangée.");
                R(ref s, "...To think that a seemingly innocent foreign exchange\r\nprogramme was a façade<E049><E003 8> <E025 3>for such Machiavellian dealings.", "...Dire qu'un programme d'échange en apparence si louable servait de façade<E049><E003 8> <E025 3>à de telles manigances machiavéliques.");
                R(ref s, "Clearly it's a plot only a government minister and high-\r\nranking judge such as the witness<E003 6> could hope to execute.", "C'est manifestement un complot que seuls un ministre et haut\r\nmagistrat comme le témoin<E003 6> pouvaient espérer mener à bien.");
                R(ref s, "Well, <E049><E003 8><E025 2>I seem to recall that it was someone on the British\r\nside who...<E049><E003 12><E025 3><E239>controlled everything.", "Eh bien, <E049><E003 8><E025 2>il me semble me souvenir que c'est du côté britannique\r\nque l'on...<E049><E003 12><E025 3><E239>orchestrait tout cela.");
                R(ref s, "Be that as it may, <E049><E003 10><E145 61 2><E025 2>it is not the place of this court to pursue\r\nthis villainous assassin exchange plot.", "Quoi qu'il en soit, <E049><E003 10><E145 61 2><E025 2>il n'appartient pas à ce tribunal de juger\r\nde ce sordide complot d'échange d'assassins.");
                R(ref s, "We are concerned only with the tangible events\r\npertaining to the murder of Inspector Gregson.", "Nous ne devons nous intéresser qu'aux faits matériels\r\nrelatifs au meurtre de l'inspecteur Gregson.");
                R(ref s, "...Is the defence clear on that point, <E049><E003 6>Counsel?", "...Est-ce bien clair pour la défense, <E049><E003 6>Maître ?");
                R(ref s, "Yes, <E049><E003 10>My Lord.<E049><E003 14>\r\n<E025 2>I'll keep that in mind as I cross-examine the witness.", "Oui, <E049><E003 10>Votre Honneur.<E049><E003 14>\r\n<E025 2>Je garderai cela à l'esprit en contre-interrogeant le témoin.");
                return s;
            };

