            // [15] BB\script\output\_sce04_c301_0040_eng#7
            entryTranslators[@"BB\script\output\_sce04_c301_0040_eng#7"] = (s) => {
                R(ref s, "On the evening in question, a member of the crew was on\r\nduty outside my cabin at all times.", "Le soir en question, un membre de l'équipage montait\r\nla garde en permanence devant ma cabine.");
                return s;
            };

            // [16] BB\script\output\_sce04_c301_0040_eng#8
            entryTranslators[@"BB\script\output\_sce04_c301_0040_eng#8"] = (s) => {
                R(ref s, "If there'd been a shot fired, the crewman would have\r\nheard it. So clearly I can't be involved.", "Si un coup de feu avait retenti, ce matelot l'aurait\r\nforcément entendu. Je ne puis donc être mêlé à cela.");
                return s;
            };

            // [17] BB\script\output\_sce04_c301_0040_eng#9
            entryTranslators[@"BB\script\output\_sce04_c301_0040_eng#9"] = (s) => {
                R(ref s, "A year ago...<E049><E003 12><E025 2>when Kazuma was still in Japan, then.", "Il y a un an...<E049><E003 12><E025 2>alors que Kazuma était encore au Japon.");
                R(ref s, "Correct.<E049><E003 12> <E025 2>It was at the examination centre for applicants\r\nfor the study tour that I approached him.", "Exact.<E049><E003 12> <E025 2>C'est au centre d'examen pour les candidats\r\nau voyage d'études que je l'ai abordé.");
                R(ref s, "I'll never forget it.<E049><E003 12>\r\n<E025 3>I remember exactly what you said.", "Je ne l'oublierai jamais.<E049><E003 12>\r\n<E025 3>Je me souviens mot pour mot de ce que vous m'avez dit.");
                R(ref s, "You just came out and asked me forthright <E049><E003 10><E025 2><E238>if I'd consider\r\ntravelling to Britain on an assassination mission.", "Vous m'avez demandé sans détours <E049><E003 10><E025 2><E238>si j'envisagerais\r\nde partir en Grande-Bretagne pour une mission d'assassinat.");
                R(ref s, "Surely not...", "Ce n'est pas possible...");
                R(ref s, "I thought it was a joke at first, <E003 4>of course.<E049><E003 10>\r\n<E025 3>But then...", "J'ai d'abord cru à une plaisanterie, <E003 4>bien sûr.<E049><E003 10>\r\n<E025 3>Mais ensuite...");
                R(ref s, "...it was made clear to me that if I didn't accept,<E049><E003 10> <E025 3>I wouldn't\r\nbe considered for the study tour.", "...on m'a signifié sans équivoque que si je refusais,<E049><E003 10> <E025 3>ma candidature\r\nau voyage d'études ne serait pas retenue.");
                R(ref s, "So, <E049><E003 8><E606>so you agreed to it...<E003 14>just for that?!", "Alors... <E049><E003 8><E606>tu as accepté...<E003 14>juste pour ça ?!");
                R(ref s, "I mean, <E049><E003 8><E025 2>I know how much you wanted to study in\r\nEngland, <E049><E003 8><E025 3>but...<E049><E003 8><E164 1 71 1 2 5 0 2 1><E139 1><E025 1>assassination?!", "Je veux dire, <E049><E003 8><E025 2>je sais à quel point tu tenais à étudier en\r\nAngleterre, <E049><E003 8><E025 3>mais...<E049><E003 8><E164 1 71 1 2 5 0 2 1><E139 1><E025 1>un assassinat ?!");
                R(ref s, "The Empire of Japan had accepted a proposal from the\r\nBritish Empire at the time.", "L'Empire du Japon avait alors accepté une proposition venant\r\nde l'Empire britannique.");
                R(ref s, "An agreement to send a student from each country to the\r\nother's <E049><E003 6>to deepen cultural understanding and friendship.", "Un accord prévoyant d'envoyer un étudiant de chaque pays chez l'autre<E049><E003 6> pour resserrer les liens d'amitié et la compréhension culturelle.");
                R(ref s, "But behind the scenes, <E049><E003 8><E025 2>the chosen students were to be\r\ngiven assassination missions.", "Mais en coulisses, <E049><E003 8><E025 2>les étudiants sélectionnés devaient se voir\r\nconfier des missions d'assassinat.");
                R(ref s, "I...<E003 12>had no choice but to accept the proposal that originated\r\nfrom my British counterpart.", "Je...<E003 12>n'ai eu d'autre choix que d'accepter la requête émanant\r\nde mon homologue britannique.");
                R(ref s, "Why?<E049><E003 15> <E341><E025 2>Why didn't you expose the plot there and then?!", "Pourquoi ?<E049><E003 15> <E341><E025 2>Pourquoi ne pas avoir dénoncé ce complot sur-le-champ ?!");
                R(ref s, "Britain acknowledges no part in these alleged misbegotten\r\ndealings.", "La Grande-Bretagne ne reconnaît aucune implication dans ces prétendues\r\nmanœuvres illicites.");
                R(ref s, "I advise you not to make spurious allegations...<E049><E003 12>\r\n<E025 3>Foreign Minister Jigoku.", "Je vous conseille de ne pas proférer de calomnies inconsidérées...<E049><E003 12>\r\n<E025 3>Monsieur le Ministre Jigoku.");
                R(ref s, "As a witness, <E049><E003 6>I am bound to tell the truth...<E003 12><E025 3>My Lord.", "En tant que témoin, <E049><E003 6>je suis tenu de dire la vérité...<E003 12><E025 3>Votre Honneur.");
                R(ref s, "Anyway, <E049><E003 8>I picked Asogi, <E049><E003 8>and explained the details of the\r\nplan to him.", "Quoi qu'il en soit, <E049><E003 8>j'ai choisi Asogi, <E049><E003 8>et je lui ai expliqué les détails\r\ndu plan.");
                return s;
            };

            // [18] BB\script\output\_sce04_c301_0040_eng#10
            entryTranslators[@"BB\script\output\_sce04_c301_0040_eng#10"] = (s) => {
                R(ref s, "Why Kazuma?<E049><E003 10> <E025 2><E341>Why did you pick him as the assassin?", "Pourquoi Kazuma ?<E049><E003 10> <E025 2><E341>Pourquoi l'avoir choisi comme assassin ?");
                R(ref s, "He was the most capable of all the applicants.<E049><E003 10>\r\n<E025 3>And in addition...", "Il était le plus brillant de tous les candidats.<E049><E003 10>\r\n<E025 3>Et de surcroît...");
                R(ref s, "...I knew his desire to travel to Britain was very strong.", "...je savais que son désir de se rendre en Grande-Bretagne était immense.");
                R(ref s, "In fact, <E049><E003 8><E025 2>it was almost more than a desire.<E049><E003 8><E145 47 77><E003 5>\r\n<E025 3><E239>It was his whole purpose in life.", "En réalité, <E049><E003 8><E025 2>c'était bien plus qu'un simple désir.<E049><E003 8><E145 47 77><E003 5>\r\n<E025 3><E239>C'était la raison même de son existence.");
                R(ref s, "(Yes, <E003 8><E025 2>as his best friend, <E003 6>I can certainly attest to that.)", "(Oui, <E003 8><E025 2>en tant que meilleur ami, <E003 6>je peux certainement en témoigner.)");
                R(ref s, "(The way he threw himself into his studies...<E003 10>\r\nThe way he pursued becoming qualified as a lawyer...)", "(L'acharnement qu'il mettait dans ses études...<E003 10>\r\nSon dévouement pour devenir un avocat qualifié...)");
                R(ref s, "(It was all ultimately for that one single goal of being\r\naccepted on a study tour to Britain.)", "(Tout cela n'avait finalement qu'un seul but : être retenu\r\npour ce voyage d'études en Grande-Bretagne.)");
                R(ref s, "And of course, <E049><E003 10><E025 2>we know the reason behind that.", "Et bien sûr, <E049><E003 10><E025 2>nous connaissons tous la raison sous-jacente.");
                R(ref s, "He was determined to find out for himself the truth about\r\nhis father, <E049><E003 8><E025 3>Genshin Asogi.", "Il était déterminé à découvrir par lui-même la vérité au sujet\r\nde son père, <E049><E003 8><E025 3>Genshin Asogi.");
                R(ref s, "There's nothing I wouldn't have done to get here.", "Il n'y a rien que je n'aurais refusé de faire pour venir ici.");
                R(ref s, "Be that agreeing to assume the role of an assassin...<E049><E003 10><E145 112 65><E117 112 13><E003 7>\r\n<E025 3><E238>or betraying people's trust.", "Que ce soit endosser le rôle d'un assassin...<E049><E003 10><E145 112 65><E117 112 13><E003 7>\r\n<E025 3><E238>ou trahir la confiance d'autrui.");
                R(ref s, "Well, <E049><E003 8><E145 47 82><E117 47 20><E003 10><E025 2><E333>you certainly did a fine job of betraying mine,<E049><E003 8> <E025 3>Asogi.", "Eh bien, <E049><E003 8><E145 47 82><E117 47 20><E003 10><E025 2><E333>tu as parfaitement réussi à trahir la mienne,<E049><E003 8> <E025 3>Asogi.");
                R(ref s, "But why <E049><E003 10><E145 1 85><E025 2>was Inspector Gregson the target?", "Mais pourquoi <E049><E003 10><E145 1 85><E025 2>l'inspecteur Gregson était-il la cible ?");
                R(ref s, "I have no idea.<E049><E003 10> <E145 47 77><E118 47 1.2><E025 2>Those were the orders from Britain.<E049><E003 10>\r\nI was in no position to question them.", "Je n'en ai aucune idée.<E049><E003 10> <E145 47 77><E118 47 1.2><E025 2>Tels étaient les ordres venus de Grande-Bretagne.<E049><E003 10>\r\nJe n'étais pas en position de les contester.");
                R(ref s, "You have no idea?<E049><E003 10> Really?<E049><E003 8><E146 112 4><E118 112 1.2><E149 112 0 4><E003 15>\r\n<E025 3><E238>I find that hard to believe.", "Vous n'en avez aucune idée ?<E049><E003 10> Vraiment ?<E049><E003 8><E146 112 4><E118 112 1.2><E149 112 0 4><E003 15>\r\n<E025 3><E238>J'ai peine à le croire.");
                R(ref s, "Oh <E049><E003 6>do you?", "Ah, <E049><E003 6>vraiment ?");
                R(ref s, "Judge Jigoku was once a visiting student here in Britain\r\nhimself, <E003 4>of course.", "Le juge Jigoku a lui-même été étudiant stagiaire ici en Grande-Bretagne\r\nautrefois, <E003 4>bien sûr.");
                R(ref s, "Perhaps he has some connection with Inspector Gregson\r\nfrom that time...", "Peut-être entretenait-il des liens avec l'inspecteur Gregson\r\ndepuis cette époque...");
                R(ref s, "The defence really ought to catch up.", "La défense devrait vraiment se mettre à la page.");
                R(ref s, "With what?", "Sur quoi donc ?");
                R(ref s, "With the fact that the assassin exchange <E049><E003 10><E025 3><E330>has absolutely\r\nnothing to do with the case under scrutiny here.", "Sur le fait que cet échange d'assassins <E049><E003 10><E025 3><E330>n'a absolument\r\nrien à voir avec le procès qui nous réunit ici.");
                R(ref s, "Yes, <E049><E003 8><E025 2>I've already admitted to recruiting Asogi...", "Oui, <E049><E003 8><E025 2>j'ai déjà reconnu avoir recruté Asogi...");
                return s;
            };

            // [19] BB\script\output\_sce04_c301_0040_eng#11
            entryTranslators[@"BB\script\output\_sce04_c301_0040_eng#11"] = (s) => {
                R(ref s, "I presume <E049><E003 15><E333><E025 2>you're referring to <E006>the incident<E005> that occurred\r\nduring Kazuma's passage to Britain in January?", "Je présume <E049><E003 15><E333><E025 2>que vous faites allusion à <E006>l'incident<E005> survenu\r\nlors de la traversée de Kazuma vers la Grande-Bretagne en janvier ?");
                R(ref s, "The awful ‘tragedy’ that took place on the steamship...", "La terrible « tragédie » survenue sur ce navire à vapeur...");
                R(ref s, "Word arrived at the ministry some two weeks after the\r\nship's departure from our shores.", "La nouvelle est parvenue au ministère environ deux semaines après\r\nque le bâtiment a quitté nos côtes.");
                R(ref s, "The visiting student had been killed, <E049><E003 8><E145 47 71><E003 8><E025 2><E239>but his body had\r\nsomehow <E006>gone missing<E005> in Hong Kong.", "L'étudiant en mission avait péri, <E049><E003 8><E145 47 71><E003 8><E025 2><E239>mais son corps avait\r\nmystérieusement <E006>disparu<E005> à Hong Kong.");
                R(ref s, "The news was wired to me from a detective I'd placed on\r\nthe ship to accompany the assassin.", "Cette information m'a été télégraphiée par un détective que j'avais posté\r\nsur le navire pour surveiller l'assassin.");
                R(ref s, "Obviously, <E049><E003 8><E025 2>Kazuma didn't actually die at all.", "À l'évidence, <E049><E003 8><E025 2>Kazuma n'était pas mort du tout.");
                R(ref s, "But he did lose his memory.<E049><E003 12>\r\n<E025 2>Including all details about his special mission.", "Mais il a bel et bien perdu la mémoire.<E049><E003 12>\r\n<E025 2>Y compris tous les détails concernant sa mission spéciale.");
                R(ref s, "Did you not consider <E145 61 7><E118 61 0.7>dispatching another assassin at that\r\npoint?", "N'avez-vous pas songé <E145 61 7><E118 61 0.7>à dépêcher un autre assassin à ce\r\nmoment-là ?");
                R(ref s, "That wasn't possible.<E049><E003 12>\r\n<E025 3>Simply because...", "C'était impossible.<E049><E003 12>\r\n<E025 3>Pour la simple raison...");
                R(ref s, "...that black-clad young student over there had already\r\nput himself forward as Asogi's replacement.", "...que ce jeune étudiant vêtu de noir là-bas s'était déjà\r\nproposé comme remplaçant d'Asogi.");
                R(ref s, "And there was no way to stop him from reaching Britain.", "Et il n'y avait aucun moyen de l'empêcher d'atteindre la Grande-Bretagne.");
                R(ref s, "My hands were completely tied.", "J'avais les mains totalement liées.");
                R(ref s, "So Mr Sholmes's strategy worked perfectly.", "La stratégie de M. Sholmes a donc fonctionné à merveille.");
                R(ref s, "He, <E003 10><E025 2>he predicted everything that would happen...", "Il, <E003 10><E025 2>il avait tout prédit...");
                R(ref s, "Months later, <E049><E003 8>my memory returned.", "Des mois plus tard, <E049><E003 8>ma mémoire est revenue.");
                R(ref s, "But I'd never intended to go through with the\r\nassassination mission anyway.", "Mais je n'avais de toute façon nulle intention d'aller au bout\r\nde cette mission d'assassinat.");
                R(ref s, "So you were playing me right from the outset, <E049><E003 6><E025 3>were you?<E049><E003 12>\r\nIs that it?", "Ainsi vous vous êtes joué de moi dès le départ, <E049><E003 6><E025 3>n'est-ce pas ?<E049><E003 12>\r\nC'est bien cela ?");
                R(ref s, "I'd sooner be guilty of that crime than of taking someone\r\nelse's life.", "Je préfère encore être coupable de cela que d'avoir ôté la vie\r\nà un semblable.");
                R(ref s, "I was prepared to do whatever I had to <E049><E003 6><E145 112 4><E118 112 1.15><E149 112 0 4><E003 6>in order to get\r\nmyself here to Britain.", "J'étais prêt à tout ce qui était nécessaire <E049><E003 6><E145 112 4><E118 112 1.15><E149 112 0 4><E003 6>pour parvenir\r\nici, en Grande-Bretagne.");
                R(ref s, "This line of questioning has gone on long enough.", "Cette série de questions n'a que trop duré.");
                R(ref s, "All the court should be concerned about in the testimony\r\ngiven by this witness...", "Tout ce qui doit intéresser ce tribunal dans la déposition\r\nde ce témoin...");
                R(ref s, "...are details relating to his relationship with Inspector\r\nGregson, <E049><E003 8><E025 3>and the victim's murder.", "...ce sont les détails relatifs à ses rapports avec l'inspecteur\r\nGregson, <E049><E003 8><E025 3>et au meurtre de la victime.");
                R(ref s, "In that case...", "Dans ce cas...");
                R(ref s, "...as I've already made perfectly clear, <E049><E003 8><E025 1><E239>I had no connection\r\nto the man or his death!", "...comme je l'ai déjà clairement indiqué, <E049><E003 8><E025 1><E239>je n'avais aucun lien\r\navec cet homme, ni avec sa mort !");
                R(ref s, "And you have some means of substantiating this plea?", "Et vous disposez d'un élément pour étayer cette affirmation ?");
                return s;
            };

            // [20] BB\script\output\_sce04_c301_0040_eng#12
            entryTranslators[@"BB\script\output\_sce04_c301_0040_eng#12"] = (s) => {
                R(ref s, "Outside your cabin in the first-class area of the\r\nSS Grouse, <E049><E003 6>you mean?", "Devant votre cabine dans la section de première classe du\r\nSS Grouse, <E049><E003 6>voulez-vous dire ?");
                R(ref s, "Yes, <E049><E003 8>that's right.", "Oui, <E049><E003 8>c'est exact.");
                R(ref s, "Not least because there was a ‘murder’ of a student\r\npassenger earlier in the year, <E049><E003 8><E025 3>I imagine...", "D'autant plus qu'il y a eu le « meurtre » d'un étudiant\r\npassager plus tôt dans l'année, <E049><E003 8><E025 3>j'imagine...");
                R(ref s, "...the liner operators have taken to posting a crewman\r\noutside every first-class cabin door.", "...la compagnie a pris l'habitude de poster un matelot\r\ndevant la porte de chaque cabine de première classe.");
                R(ref s, "I can confirm the presence of the crewman guard myself.", "Je peux attester moi-même de la présence de cette sentinelle.");
                R(ref s, "What do you mean?", "Que voulez-vous dire ?");
                R(ref s, "Because I accompanied Inspector Gregson to Dunkirk that\r\nnight, <E049><E003 8><E025 3>I witnessed it with my own eyes.", "Ayant accompagné l'inspecteur Gregson à Dunkerque cette\r\nnuit-là, <E049><E003 8><E025 3>je l'ai constaté de mes propres yeux.");
                R(ref s, "There was a well-built crewman standing guard directly\r\nin front of the door to the witness's cabin.", "Un matelot solidement bâti montait la garde juste\r\ndevant la porte de la cabine du témoin.");
                R(ref s, "At that particular time, <E003 4>of course, <E049><E003 8><E145 47 64><E003 6><E025 2>I'd gone to the ship's\r\ndining room for dinner.", "À ce moment précis, <E003 4>bien sûr, <E049><E003 8><E145 47 64><E003 6><E025 2>j'étais allé dîner\r\ndans la salle à manger du paquebot.");
                R(ref s, "The inspector and I asked the crewman to allow us into\r\nthe cabin while we waited for Judge Jigoku's return.", "L'inspecteur et moi avons demandé au matelot de nous laisser entrer\r\ndans la cabine en attendant le retour du juge Jigoku.");
                R(ref s, "I suppose Inspector Gregson was there in his capacity\r\nas the Reaper...", "J'imagine que l'inspecteur Gregson était là en sa qualité\r\nde Faucheur...");
                R(ref s, "He was intending to take the witness's life.", "Il avait l'intention d'ôter la vie au témoin.");
                R(ref s, "Exactly.<E049><E003 10> <E025 2>As I've said numerous times now, <E049><E003 8><E025 3>I had no\r\nintention of killing anyone.", "Exactement.<E049><E003 10> <E025 2>Comme je l'ai déjà dit à maintes reprises, <E049><E003 8><E025 3>je n'avais\r\naucune intention de tuer qui que ce soit.");
                R(ref s, "So the crewman let two <E006>potential assassins<E005> into the cabin\r\nhe was supposed to be guarding?", "Donc le garde a laissé entrer deux <E006>assassins potentiels<E005> dans la cabine\r\nqu'il était censé protéger ?");
                R(ref s, "Not the most convincing of sentries, <E049><E003 6>really.", "Pas la plus rigoureuse des sentinelles, <E049><E003 6>en vérité.");
                R(ref s, "In truth, <E049><E003 8><E145 112 70><E003 10><E238>those were my thoughts, too.", "À vrai dire, <E049><E003 8><E145 112 70><E003 10><E238>c'est exactement ce que j'ai pensé.");
                R(ref s, "But anyway, <E049><E003 10>I stayed to talk with Inspector Gregson for a\r\nshort while...", "Quoi qu'il en soit, <E049><E003 10>je suis resté m'entretenir un instant avec l'inspecteur\r\nGregson...");
                R(ref s, "...and then I left him there <E049><E003 8>and made my way off the ship\r\nalone.", "...puis je l'ai laissé là <E049><E003 8>et j'ai débarqué du navire\r\nseul.");
                R(ref s, "Was the guard still at the door when you went?", "La sentinelle était-elle toujours à la porte lors de votre départ ?");
                R(ref s, "Yes.<E049><E003 10> <E145 112 14><E118 112 1.5><E003 6><E025 2>He glared at me as I walked past.", "Oui.<E049><E003 10> <E145 112 14><E118 112 1.5><E003 6><E025 2>Il m'a lancé un regard noir quand je suis passé devant lui.");
                R(ref s, "You see?<E049><E003 12> <E025 3>That proves it.", "Vous voyez ?<E049><E003 12> <E025 3>Voilà qui le prouve.");
                return s;
            };

            // [21] BB\script\output\_sce04_c301_0040_eng#13
            entryTranslators[@"BB\script\output\_sce04_c301_0040_eng#13"] = (s) => {
                R(ref s, "The crewman who was standing directly outside your\r\ncabin door, <E049><E003 6><E025 3>you mean?", "Le matelot qui se tenait juste devant la porte de votre\r\ncabine, <E049><E003 6><E025 3>voulez-vous dire ?");
                R(ref s, "That's right.", "C'est bien cela.");
                R(ref s, "A muscular man with a permanent grim expression on his\r\nface.<E049><E003 10> <E025 3>He didn't once move from that spot.", "Un gaillard musclé au visage perpétuellement renfrogné.<E049><E003 10> <E025 3>Il n'a pas bougé d'un pouce de son poste.");
                R(ref s, "To be honest, <E049><E003 6><E025 2>I thought he was a miserable fellow.", "Pour être franc, <E049><E003 6><E025 2>j'ai trouvé que c'était un sinistre personnage.");
                R(ref s, "But as it happens, <E049><E003 12><E145 47 68><E118 47 1.3><E045><E025 2>he's a vital witness <E342>now!", "Mais il se trouve qu'il est désormais <E049><E003 12><E145 47 68><E118 47 1.3><E045><E025 2>un témoin capital <E342>à présent !");
                R(ref s, "There's no doubt <E049><E003 10><E025 2><E333>that Gregson was killed by a gunshot.", "Il ne fait aucun doute <E049><E003 10><E025 2><E333>que Gregson a été tué par balle.");
                R(ref s, "And it's inconceivable <E049><E003 8><E025 2>that a crewman standing just\r\noutside the cabin door wouldn't have heard that.", "Et il est impensable <E049><E003 8><E025 2>qu'un garde posté juste\r\ndevant la porte de la cabine n'ait rien entendu.");
                R(ref s, "But wait!<E049><E003 12> <E025 2>What about the ship's enormous steam engines?", "Mais attendez !<E049><E003 12> <E025 2>Et les gigantesques machines à vapeur du paquebot ?");
                R(ref s, "The noise of them <E049><E003 6><E164 9 87 1 2 6 0 0 1><E149 9 4 7><E139 9><E025 1>could have drowned out the sound of\r\nthe gun being fired!", "Leur vacarme assourdissant <E049><E003 6><E164 9 87 1 2 6 0 0 1><E149 9 4 7><E139 9><E025 1>aurait très bien pu couvrir\r\nla détonation d'un coup de feu !");
                R(ref s, "Sadly, <E049><E003 6><E025 2>young judicial assistant, <E049><E003 8><E025 3>that won't wash.", "Hélas, <E049><E003 6><E025 2>jeune assistante juridique, <E049><E003 8><E025 3>cette hypothèse ne tient pas debout.");
                R(ref s, "You will recall that my cabin was in the first-class area of\r\nthe ship, <E049><E003 8>which is also of course, <E049><E003 8><E025 3>the quietest.", "Vous vous souviendrez que ma cabine se trouvait en première classe,<E049><E003 8> soit la zone la plus calme <E049><E003 8><E025 3>du navire.");
                R(ref s, "Don't imagine <E342>for a moment that it's <E341>anything like steerage\r\nwhere the judicial assistants go!", "N'allez pas imaginer <E342>un instant que cela ressemble à l'entrepont <E341>où\r\nlogent les assistants juridiques !");
                R(ref s, "I, <E049><E003 8>I didn't mean...", "Je, <E049><E003 8>je ne voulais pas dire...");
                R(ref s, "But a hole like that made by a bullet was found in your\r\ncabin, <E049><E003 8><E341>Judge Jigoku!", "Mais un trou semblable à celui d'une balle a été retrouvé dans votre\r\ncabine, <E049><E003 8><E341>juge Jigoku !");
                R(ref s, "That's compelling evidence <E049><E003 8><E164 1 8 1 2 8 0 1 1><E139 1><E025 1>that a gun was fired in there!", "C'est une preuve flagrante <E049><E003 8><E164 1 8 1 2 8 0 1 1><E139 1><E025 1>qu'une arme à feu y a retenti !");
                R(ref s, "What's that?<E049><E003 10> <E025 3>A bullet hole...?", "Qu'entendez-vous par là ?<E049><E003 10> <E025 3>Un trou de balle... ?");
                R(ref s, "Oh yes.<E049><E003 12> <E145 47 78><E025 2>You're talking about what the detective\r\nuncovered in the wall yesterday, <E049><E003 6>I presume.", "Ah oui.<E049><E003 12> <E145 47 78><E025 2>Vous parlez de ce que le détective\r\na mis au jour dans la cloison hier, <E049><E003 6>je présume.");
                R(ref s, "That was obviously a rotten panel eaten out by\r\nwoodworm.<E049><E003 10> <E145 47 82><E117 47 15><E025 3>No doubt he didn't find an actual bullet.", "Il s'agissait manifestement d'un panneau pourri rongé par\r\nles vers.<E049><E003 10> <E145 47 82><E117 47 15><E025 3>Il n'a d'ailleurs trouvé aucun projectile.");
                R(ref s, "(That's the hole in this argument...)", "(C'est bien là la faille de ce raisonnement...)");
                R(ref s, "Sadly, <E049><E003 8><E025 2>I was unable to arrange for the crewman to be\r\nbrought back to Britain with me.", "Malheureusement, <E049><E003 8><E025 2>je n'ai pas pu faire en sorte que ce matelot\r\nm'accompagne en Grande-Bretagne.");
                R(ref s, "But obviously, <E049><E003 10><E025 2>if a gun had been fired in my cabin on the\r\nnight in question as the defence implies...", "Mais à l'évidence, <E049><E003 10><E025 2>si un coup de feu avait retenti dans ma cabine le soir\r\nen question comme la défense le prétend...");
                R(ref s, "...I would have been <E342>arrested on the spot, <E049><E003 8>and would\r\nnever have made it to Britain in the first place!", "...j'aurais été <E342>arrêté sur-le-champ, <E049><E003 8>et je n'aurais\r\njamais pu poser le pied en Grande-Bretagne !");
                R(ref s, "Very true.<E049><E003 10>\r\n<E025 2>The witness's logic is sound.", "C'est indéniable.<E049><E003 10>\r\n<E025 2>La logique du témoin est imparable.");
                R(ref s, "Since <E006>no gunshot was heard<E005> from the witness's cabin on\r\nthe night in question...", "Puisqu'<E006>aucun coup de feu n'a été entendu<E005> depuis la cabine du témoin\r\nla nuit des faits...");
                R(ref s, "...we must assume that the witness is telling the truth.", "...nous devons en déduire que le témoin dit la vérité.");
                R(ref s, "Heh <E003 6>heh <E003 6>heh<E025 0>...<E003 20><E169 47 3>\r\n<E025 2>I'm glad you've seen sense, <E049><E003 6>My Lord.", "Hé <E003 6>hé <E003 6>hé<E025 0>...<E003 20><E169 47 3>\r\n<E025 2>Je suis ravi que vous reveniez à la raison, <E049><E003 6>Votre Honneur.");
                return s;
            };

            // [22] BB\script\output\_sce04_c301_0040_eng#14
            entryTranslators[@"BB\script\output\_sce04_c301_0040_eng#14"] = (s) => {
                R(ref s, "(I know Kazuma's already admitted to taking on this\r\nincredible assassination plot, <E003 8><E025 3>but even so...)", "(Je sais que Kazuma a déjà admis avoir accepté ce\r\nterrible projet d'assassinat, <E003 8><E025 3>mais malgré tout...)");
                R(ref s, "(...hearing it confirmed by somebody else <E003 10><E025 3><E341>is still a real\r\nshock.)", "(...l'entendre confirmer par un tiers <E003 10><E025 3><E341>reste un véritable\r\nchoc.)");
                R(ref s, "It's unforgivable!", "C'est impardonnable !");
                R(ref s, "Using Kazuma-sama's feelings to manipulate him<E049><E003 2><E025 1><E145 9 15><E149 9 4 4><E139 9><E346> into\r\nagreeing to such a despicable plan...", "Se servir des sentiments de maître Kazuma pour le manipuler<E049><E003 2><E025 1><E145 9 15><E149 9 4 4><E139 9><E346> et\r\nle contraindre à accepter un dessein si méprisable...");
                R(ref s, "But I think Kazuma manipulated Judge Jigoku, too.<E145 9 17><E149 9 0 0><E117 9 20><E003 14>\r\n<E025 2><E330>He completely double-crossed him.", "Mais je crois que Kazuma a également manipulé le juge Jigoku.<E145 9 17><E149 9 0 0><E117 9 20><E003 14>\r\n<E025 2><E330>Il l'a complètement doublé.");
                R(ref s, "Oh dear...<E003 12> <E025 2>It's hard not to see that as a stroke of brilliance\r\non Kazuma-sama's part...", "Mon Dieu...<E003 12> <E025 2>Difficile de ne pas y voir un trait de génie\r\nde la part de maître Kazuma...");
                R(ref s, "(One way or another, though, <E003 8><E025 3>Gregson ended up dead.)", "(D'une manière ou d'une autre, pourtant, <E003 8><E025 3>Gregson a fini par mourir.)");
                R(ref s, "I really think that the murder <E145 9 17><E117 9 35>must have happened aboard\r\nthat steamship.", "Je suis convaincu que le meurtre <E145 9 17><E117 9 35>s'est bien produit à bord\r\nde ce navire à vapeur.");
                R(ref s, "So you mean...", "Vous voulez dire...");
                R(ref s, "Judge Jigoku must be <E006>lying<E005>.", "Le juge Jigoku <E006>ment<E005> nécessairement.");
                R(ref s, "I know I shouldn't let my emotions cloud my judgement...", "Je sais que je ne devrais pas laisser mes sentiments embrumer mon jugement...");
                R(ref s, "...but you must destroy him, <E049><E003 8>Mr Naruhodo!", "...mais vous devez le terrasser, <E049><E003 8>M. Naruhodo !");
                return s;
            };

            // [23] BB\script\output\_sce04_c301_0040_eng#23
            entryTranslators[@"BB\script\output\_sce04_c301_0040_eng#23"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu assez de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît clairement <E049><E003 8><E025 2>que toute discussion supplémentaire sur cette affaire\r\nsera stérile.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Drake Van Peers, <E049><E003 8><E025 2>j'ose espérer que, bien qu'égaré...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "...vous avez néanmoins agi au nom de la justice.<E049><E003 12>\r\n<E025 3>Même s'il m'en coûte d'en arriver à cette conclusion...");
                R(ref s, "No!<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Wait, My Lord!", "Non !<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de ce tribunal, <E049><E003 6><E025 3>je déclare\r\npar la présente l'accusé, <E049><E003 6><E025 3>Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "L'affaire est entendue.<E049><E003 10>\r\n<E025 2>L'audience est levée !");
                return s;
            };

            // [24] BB\script\output\_sce04_c301_0050_eng#2
            entryTranslators[@"BB\script\output\_sce04_c301_0050_eng#2"] = (s) => {
                R(ref s, "Yes,<E049><E003 8><E025 2> as the court has heard, <E049><E003 8><E025 2>there was a crewman posted\r\noutside Judge Jigoku's cabin.", "Oui,<E049><E003 8><E025 2> comme la cour a pu l'entendre, <E049><E003 8><E025 2>un matelot montait la garde\r\ndevant la cabine du juge Jigoku.");
                R(ref s, "However, <E049><E003 8><E025 2>we can be sure that, <E049><E003 8>contrary to the witness's\r\nclaim...", "Toutefois, <E049><E003 8><E025 2>nous pouvons être certains que, <E049><E003 8>contrairement aux affirmations\r\ndu témoin...");
                R(ref s, "...the guard wasn't there at all times.", "...la sentinelle ne s'y trouvait pas en permanence.");
                R(ref s, "I have here a notice <E049><E003 10><E060 0 164 1 0><E145 1 85><E003 12><E025 2>of a particular event that was\r\nscheduled to take place aboard the steamship on the 31st.", "J'ai ici un avis officiel <E049><E003 10><E060 0 164 1 0><E145 1 85><E003 12><E025 2>concernant un événement bien particulier\r\nqui devait avoir lieu à bord du navire le 31.");
                R(ref s, "Wha...?!<E049><E003 16> <E025 1><E045>Where did you get that?!", "Quoi... ?!<E049><E003 16> <E025 1><E045>Où avez-vous obtenu cela ?!");
                R(ref s, "It's evidence gathered by Mr Herlock Sholmes.", "C'est une pièce réunie par M. Herlock Sholmes.");
                R(ref s, "You were acquainted yesterday, <E049><E003 8>if you remember.", "Vous avez fait connaissance hier, <E049><E003 8>si vous vous souvenez bien.");
                R(ref s, "Herlock Sholmes again...", "Encore Herlock Sholmes...");
                R(ref s, "According to this itinerary...", "D'après cet avis de service...");
                R(ref s, "...after leaving the Port of Dunkirk, <E049><E003 6>at exactly 10 p.m.,<E049><E003 6> and\r\nfor a period of twenty minutes...", "...après le départ du port de Dunkerque, <E049><E003 6>à 22 heures précises,<E049><E003 6> et\r\npendant une durée de vingt minutes...");
                R(ref s, "...all crewmen of the SS Grouse were to gather on deck<E049><E003 10>\r\n<E145 1 0><E118 1 1.5><E003 12><E330>for an evacuation drill.", "...tous les membres d'équipage du SS Grouse devaient se réunir sur le pont<E049><E003 10>\r\n<E145 1 0><E118 1 1.5><E003 12><E330>pour un exercice d'évacuation.");
                R(ref s, "All crewmen were...<E003 14><E025 1><E331><E006>away from their posts<E005>?!", "Tous les matelots étaient... <E003 14><E025 1><E331><E006>éloignés de leur poste<E005> ?!");
                R(ref s, "And during that <E006>twenty-minute interval<E005> of course...", "Et pendant cet <E006>intervalle de vingt minutes<E005>, bien entendu...");
                R(ref s, "...any gunshots emanating from your cabin <E049><E003 8><E145 1 21><E003 15><E025 2><E333>would have\r\nbeen heard by no one!", "...tout coup de feu tiré depuis votre cabine <E049><E003 8><E145 1 21><E003 15><E025 2><E333>n'aurait\r\nété entendu par personne !");
                R(ref s, "In summary, <E049><E003 6>Judge Jigoku...", "En résumé, <E049><E003 6>juge Jigoku...");
                R(ref s, "...you had ample opportunity to commit the crime!", "...vous aviez amplement l'opportunité de commettre le crime !");
                R(ref s, "A twenty-minute window of opportunity...<E049><E003 14>\r\n<E025 2>That's an excellent find, <E003 4>Ryunosuke.", "Une fenêtre d'opportunité de vingt minutes...<E049><E003 14>\r\n<E025 2>C'est une trouvaille magistrale, <E003 4>Ryunosuke.");
                R(ref s, "But it amounts to nothing!", "Mais cela ne prouve absolument rien !");
                R(ref s, "Why?", "Pourquoi ?");
                R(ref s, "Because the witness clearly stated in his testimony <E049><E003 5><E145 112 0><E003 15><E238><E025 3>that\r\n<E006>no incident occurred<E005> in his cabin.", "Car le témoin a expressément précisé dans sa déposition <E049><E003 5><E145 112 0><E003 15><E238><E025 3>qu'<E006>aucun\r\nincident ne s'est produit<E005> dans sa cabine.");
                R(ref s, "Unless you have some decisive <E006>evidence<E005> that can show\r\nhis testimony to be false...", "À moins d'apporter une <E006>preuve<E005> formelle démontrant\r\nla fausseté de ce témoignage...");
                R(ref s, "...your accusation is nothing more than conjecture!", "...votre mise en cause n'est rien d'autre qu'une pure conjecture !");
                R(ref s, "Very true.<E049><E003 15><E145 61 7><E118 61 0.65>\r\n<E025 3>Well, Counsel?", "C'est tout à fait vrai.<E049><E003 15><E145 61 7><E118 61 0.65>\r\n<E025 3>Eh bien, Maître ?");
                R(ref s, "Inspector Gregson was killed in Judge Jigoku's cabin that\r\nnight.<E049><E003 10> <E025 3>I'm certain of it.", "L'inspecteur Gregson a bien été tué dans la cabine du juge Jigoku\r\ncette nuit-là.<E049><E003 10> <E025 3>J'en ai l'intime conviction.");
                R(ref s, "Because the defence has the evidence to prove it.", "Car la défense détient la preuve formelle qui l'atteste.");
                return s;
            };

            // [25] BB\script\output\_sce04_c301_0070_eng#2
            entryTranslators[@"BB\script\output\_sce04_c301_0070_eng#2"] = (s) => {
                R(ref s, "You will present the evidence for the defence at once,<E049><E003 6>\r\nCounsel.", "Présentez immédiatement cette preuve à la cour,<E049><E003 6>\r\nMaître.");
                return s;
            };

            // [26] BB\script\output\_sce04_c301_0070_eng#3
            entryTranslators[@"BB\script\output\_sce04_c301_0070_eng#3"] = (s) => {
                R(ref s, "What proof do you have <E049><E003 10><E025 1><E346>that the victim's life was taken in\r\nJigoku's cabin on the 31st October?", "Quelle preuve avez-vous <E049><E003 10><E025 1><E346>que la victime a été assassinée dans\r\nla cabine de Jigoku le 31 octobre ?");
                return s;
            };

            // [27] BB\script\output\_sce04_c301_0070_eng#4
            entryTranslators[@"BB\script\output\_sce04_c301_0070_eng#4"] = (s) => {
                R(ref s, "Bailiff!<E049><E003 16> Take this evidence <E049><E003 12>and incinerate it!", "Huissier !<E049><E003 16> Prenez cette pièce <E049><E003 12>et jetez-la au feu !");
                R(ref s, "No no no!<E049><E003 12> <E025 2>That evidence was presented after careful\r\nconsideration, <E049><E003 6>My Lord.", "Non, non, non !<E049><E003 12> <E025 2>Cette preuve a été versée aux débats après mûre\r\nréflexion, <E049><E003 6>Votre Honneur.");
                R(ref s, "Then I'd suggest you take a little longer over your\r\ndeliberation in future.", "Je vous conseille alors de réfléchir plus longuement la prochaine\r\nfois.");
                R(ref s, "Otherwise you may find...", "Sinon vous pourriez bien découvrir...");
                R(ref s, "...that you're the one being sent for incineration!", "...que c'est vous-même qui finirez jeté aux flammes !");
                R(ref s, "AAAAAAAAAG<E345>H!", "AAAAAAAAAG<E345>H !");
                R(ref s, "(Is it just me, <E003 10><E330><E025 3>or is Kazuma's tongue getting <E006>sharper<E007> by the\r\nminute?)", "(C'est une impression, <E003 10><E330><E025 3>ou la répartie de Kazuma devient de plus en plus <E006>tranchante<E007>\r\nà chaque minute ?)");
                R(ref s, "Don't worry, <E003 4>Mr Naruhodo.<E049><E003 4><E160 9><E118 9 1.2><E139 9>\r\n<E025 1><E346>Your mind can only get sharper, too!", "Ne vous en faites pas, <E003 4>M. Naruhodo.<E049><E003 4><E160 9><E118 9 1.2><E139 9>\r\n<E025 1><E346>Votre esprit aussi va s'aiguiser !");
                R(ref s, "(Mr Sholmes and Professor Mikotoba's visit to Judge\r\nJigoku's cabin...)", "(La visite de M. Sholmes et du professeur Mikotoba dans la cabine\r\ndu juge Jigoku...)");
                R(ref s, "(...yielded a minute piece of evidence that was very\r\nnearly overlooked, <E003 6>if my memory isn't failing me.)", "(...a permis de découvrir un minuscule indice qui avait presque failli passer\r\ninaperçu, <E003 6>si ma mémoire ne me trahit pas.)");
                R(ref s, "You must bring it to mind, Mr Naruhodo!<E049><E003 10> <E025 3>And in a timely\r\nfashion...<E003 12><E025 1>before the bailiff burns everything!", "Rappelez-vous-en, M. Naruhodo !<E049><E003 10> <E025 3>Et faites vite...<E003 12><E025 1>\r\navant que l'huissier ne brûle tout !");
                return s;
            };

            // [28] BB\script\output\_sce04_c301_0070_eng#6
            entryTranslators[@"BB\script\output\_sce04_c301_0070_eng#6"] = (s) => {
                R(ref s, "Judge Jigoku!<E049><E003 12><E060 0 159 1 0>\r\nThis was found in your cabin yesterday.", "Juge Jigoku !<E049><E003 12><E060 0 159 1 0>\r\nCeci a été retrouvé dans votre cabine hier.");
                R(ref s, "What is that?<E049><E003 10> <E145 61 5><E118 61 0.6><E003 5><E025 3><E239>The crown of a pocket watch?", "Qu'est-ce que c'est ?<E049><E003 10> <E145 61 5><E118 61 0.6><E003 5><E025 3><E239>La couronne d'une montre à gousset ?");
                R(ref s, "A, <E049><E003 8>a pocket watch...?", "U-Une montre à gousset... ?");
                R(ref s, "And if you will observe, <E049><E003 5><E145 1 0><E118 1 1.3><E149 1 0 8><E003 18>the victim's pocket watch, <E049><E003 8>which\r\nwe know he treasured...", "Et si vous voulez bien observer <E049><E003 5><E145 1 0><E118 1 1.3><E149 1 0 8><E003 18>la montre de la victime, <E049><E003 8>à laquelle\r\nil tenait tant comme nous le savons...");
                R(ref s, "...is missing precisely that part.", "...il lui manque précisément cette pièce.");
                R(ref s, "It, <E049><E003 8><E145 61 5><E118 61 0.6><E341>it can't be...", "Ce... <E049><E003 8><E145 61 5><E118 61 0.6><E341>ce n'est pas possible...");
                R(ref s, "Moreover, <E049><E003 6><E060 0 159 1 0><E145 1 0><E003 5>this crown is <E003 6><E025 3><E006>a perfect fit<E005> on the spindle\r\nprotruding from the victim's watch.", "De plus, <E049><E003 6><E060 0 159 1 0><E145 1 0><E003 5>cette couronne <E003 6><E025 3><E006>s'adapte à la perfection<E005> sur la tige\r\nqui dépasse de la montre de la victime.");
                R(ref s, "Now, <E049><E003 8><E025 2>the fact that this was retrieved from Judge Jigoku's\r\ncabin...", "Dès lors, <E049><E003 8><E025 2>le fait que cette pièce provienne de la cabine\r\ndu juge Jigoku...");
                R(ref s, "...tells us that the victim's watch almost certainly broke\r\nthere.", "...nous indique avec quasi-certitude que la montre de la victime\r\ns'y est brisée.");
                R(ref s, "Grrr...<E003 2>...<E003 4>...", "Grrr...<E003 2>...<E003 4>...");
                R(ref s, "In other words, <E049><E003 8><E025 3>the victim was killed on the 31st<E049><E003 10> during\r\nthe twenty-minute evacuation drill...", "En d'autres termes, <E049><E003 8><E025 3>la victime a été tuée le 31<E049><E003 10> pendant\r\nles vingt minutes de l'exercice d'évacuation...");
                R(ref s, "...in the cabin occupied by you, <E049><E003 15><E160 47><E130 15 1><E607><E339>Judge Jigoku!", "...dans la cabine que vous occupiez, <E049><E003 15><E160 47><E130 15 1><E607><E339>juge Jigoku !");
                R(ref s, "Well...<E003 12><E025 2>you're razor sharp, <E049><E003 6>aren't you, <E049><E003 8><E341><E025 3>you young\r\nmurderer...", "Eh bien...<E003 12><E025 2>vous avez l'esprit bien affûté, <E049><E003 6>n'est-ce pas, <E049><E003 8><E341><E025 3>jeune\r\nmeurtrier...");
                R(ref s, "Expertly manoeuvred, <E049><E003 6><E025 2>Ryunosuke.", "Brillante démonstration, <E049><E003 6><E025 2>Ryunosuke.");
                R(ref s, "And your argument sounds entirely plausible...", "Et votre raisonnement paraît tout à fait plausible...");
                R(ref s, "...at first.", "...de prime abord.");
                R(ref s, "But rather like this pocket watch, <E049><E003 10><E330>it's full of cracks.", "Mais tout comme cette montre, <E049><E003 10><E330>il est fissuré de partout.");
                R(ref s, "And I believe <E049><E003 15><E145 112 0><E118 112 0.65><E003 15><E333><E025 2>Judge Jigoku feels the same way.", "Et je crois <E049><E003 15><E145 112 0><E118 112 0.65><E003 15><E333><E025 2>que le juge Jigoku partage mon avis.");
                R(ref s, "I was wrong to acquit you earlier in the year.", "J'ai eu tort de vous acquitter plus tôt cette année.");
                R(ref s, "Sorry?", "Pardon ?");
                R(ref s, "If I'd known that it would result in anyone having to\r\nlisten to this drivel...", "Si j'avais su que cela contraindrait quiconque à devoir\r\nécouter ces sornettes...");
                R(ref s, "...I would have declared you guilty just to spare the world\r\nyour ridiculous bombast.", "...je vous aurais déclaré coupable, rien que pour épargner au monde\r\nvos ridicules grands airs.");
                R(ref s, "I think it's clear...", "Il me paraît évident...");
                R(ref s, "...that the witness will have to give further testimony.", "...que le témoin va devoir fournir un témoignage plus précis.");
                R(ref s, "When you hear what actually happened in my cabin that\r\nnight...", "Quand vous saurez ce qui s'est réellement produit dans ma cabine\r\ncette nuit-là...");
                R(ref s, "...you'll notice the pitfall into which you've stumbled.", "...vous comprendrez le piège dans lequel vous êtes tombé.");
                R(ref s, "Prior to your renewed testimony, <E049><E003 8><E025 3>I would like to clarify\r\none point:", "Avant d'entendre ce nouveau témoignage, <E049><E003 8><E025 3>je tiens à éclaircir\r\nun point :");
                R(ref s, "The fact that this part of the victim's watch was\r\ndiscovered in your cabin...", "Le fait que cette partie de la montre de la victime ait été\r\nretrouvée dans votre cabine...");
                R(ref s, "...means that you acknowledge he was there, <E049><E003 6>I presume?", "...signifie que vous admettez sa présence sur les lieux, <E049><E003 6>je présume ?");
                R(ref s, "Yes, <E049><E003 12>I do.", "Oui, <E049><E003 12>je l'admets.");
                R(ref s, "You may proceed to give your formal testimony...", "Vous pouvez faire votre déposition en bonne et due forme...");
                R(ref s, "...about what exactly happened in your cabin aboard the\r\nship on the evening of the 31st October.", "...sur ce qui s'est produit avec exactitude dans votre cabine à bord du\r\npaquebot dans la soirée du 31 octobre.");
                R(ref s, "...Of course.<E049><E003 12> As a man of the law, <E049><E003 6><E025 2>I have no intention of\r\nobstructing justice.", "...Bien entendu.<E049><E003 12> En tant qu'homme de loi, <E049><E003 6><E025 2>je n'ai nulle intention\r\nd'entraver la justice.");
