            // [29] BB\script\output\_sce04_c301_0070_eng#7
            entryTranslators[@"BB\script\output\_sce04_c301_0070_eng#7"] = (s) => {
                R(ref s, "We've wasted enough time!", "Nous avons perdu assez de temps !");
                R(ref s, "It's clear to me <E049><E003 8><E025 2>that any further discussion of this case will\r\nbe fruitless.", "Il m'apparaît clairement <E049><E003 8><E025 2>que toute discussion supplémentaire sur cette affaire\r\nsera stérile.");
                R(ref s, "Barok van Zieks, <E049><E003 8><E025 2>I would like to think that however\r\nmisguided...", "Drake Van Peers, <E049><E003 8><E025 2>j'ose espérer que, bien qu'égaré...");
                R(ref s, "...you acted out of a sense of justice nonetheless.<E049><E003 12>\r\n<E025 3>Though it pains me to have reached this conclusion...", "...vous avez néanmoins agi au nom de la justice.<E049><E003 12>\r\n<E025 3>Même s'il m'en coûte d'en arriver à cette conclusion...");
                R(ref s, "No!<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Wait, My Lord!", "Non !<E049><E003 8>\r\n<E025 1><E164 1 71 1 2 1 0 2 1><E139 1>Attendez, Votre Honneur !");
                R(ref s, "In accordance with the findings of this court, <E049><E003 6><E025 3>I hereby\r\npronounce the defendant, <E049><E003 6><E025 3>Barok van Zieks...", "Conformément aux conclusions de ce tribunal, <E049><E003 6><E025 3>je déclare\r\npar la présente l'accusé, <E049><E003 6><E025 3>Drake Van Peers...");
                R(ref s, "That concludes business.<E049><E003 10>\r\n<E025 2>Court is adjourned!", "L'affaire est entendue.<E049><E003 10>\r\n<E025 2>L'audience est levée !");
                return s;
            };

            // [30] BB\script\output\_sce04_c302_0000_eng#2
            entryTranslators[@"BB\script\output\_sce04_c302_0000_eng#2"] = (s) => {
                R(ref s, "– The Events in the Cabin –", "– Les événements dans la cabine –");
                R(ref s, "I had a guest waiting for me when I returned to my cabin\r\nafter finishing my evening meal in the dining room.", "Un visiteur m'attendait quand je suis retourné à ma cabine\r\naprès mon dîner dans la salle à manger.");
                R(ref s, "When I walked through the door, <E049><E003 6>a mustachioed\r\nEnglishman was there, <E049><E003 8>foolishly waving a gun at me.", "Quand j'ai franchi la porte, <E049><E003 6>un Anglais moustachu\r\ns'y trouvait, <E049><E003 8>pointant stupidement un revolver sur moi.");
                R(ref s, "I soon took care of him with an ippon seoi throw, though.<E049><E003 10>\r\n<E025 3>He couldn't wait to run away after that.", "Mais je l'ai vite maîtrisé d'un mouvement d'ippon-seoi.<E049><E003 10>\r\n<E025 3>Après quoi il s'est empressé de prendre la fuite.");
                R(ref s, "I imagine his watch was broken when I threw him over\r\nmy shoulder.<E049><E003 12> <E145 47 66><E118 47 1.4><E025 3>It has nothing to do with his murder.", "J'imagine que sa montre s'est brisée quand je l'ai projeté par-dessus\r\nmon épaule.<E049><E003 12> <E145 47 66><E118 47 1.4><E025 3>Cela n'a rien à voir avec son meurtre.");
                R(ref s, "The inspector was clearly killed having returned to\r\nBritain.<E049><E003 12> <E025 3>Because his body was found in London.", "L'inspecteur a manifestement été tué après être retourné en\r\nGrande-Bretagne.<E049><E003 12> <E025 3>Puisque son cadavre a été retrouvé à Londres.");
                return s;
            };

