            entryTranslators[@"BB\script\output\_sce04_c302_0000_eng#3"] = (s) => {
                R(ref s, "‘Ippon seoi’...?", "« Ippon-seoi »... ?");
                R(ref s, "A common jujutsu martial arts technique in my country.", "Une prise martiale classique du jujitsu de mon pays.");
                R(ref s, "I was careful not to use too much force, <E049><E003 8><E025 2>but the man\r\nobviously landed too heavily for his watch to take.", "J'ai pris garde à ne pas forcer, <E049><E003 8><E025 2>mais l'homme est tombé\r\ntrop lourdement pour que sa montre y résiste.");
                R(ref s, "So <E049><E003 8><E025 3>Ryunosuke Naruhodo...", "Ainsi donc, <E049><E003 8><E025 3>Ryunosuke Naruhodo...");
                R(ref s, "...I imagine you can see <E006>the flaw<E005> in your logic now,<E049><E003 6><E025 3> can't\r\nyou?", "...j'imagine que vous apercevez désormais <E006>la faille<E005> de votre raisonnement,<E049><E003 6><E025 3> n'est-ce\r\npas ?");
                R(ref s, "The fact <E145 112 0><E118 112 0.55>that the pocket watch was broken in the\r\nwitness's cabin...", "Le fait <E145 112 0><E118 112 0.55>que la montre à gousset ait été brisée dans la cabine\r\ndu témoin...");
                R(ref s, "...in no way proves that the victim's murder took place\r\nthere!", "...ne démontre absolument pas que le meurtre de la victime s'y est\r\ndéroulé !");
                R(ref s, "AAAAAARGH!", "AAAAAARGH !");
                R(ref s, "I've no doubt the inspector intended to kill me.", "Je ne doute pas que l'inspecteur avait l'intention de me tuer.");
                R(ref s, "But he didn't manage to pull the trigger.", "Mais il n'a pas réussi à presser la détente.");
                R(ref s, "Yes, <E049><E003 8><E025 2>because he was merely the tactician.<E049><E003 10>\r\n<E025 2>Not the Reaper's hand of death.", "Oui, <E049><E003 8><E025 2>car il n'était que l'exécutant tactique.<E049><E003 10>\r\n<E025 2>Pas le bras armé du Faucheur.");
                R(ref s, "Well, <E049><E003 10><E025 2><E145 61 7><E118 61 0.6><E239>the testimony appears to make perfect sense as far\r\nas I can tell.", "Eh bien, <E049><E003 10><E025 2><E145 61 7><E118 61 0.6><E239>ce témoignage paraît parfaitement cohérent pour autant\r\nque je puisse en juger.");
                R(ref s, "Let me express my deep gratitude for your\r\nunderstanding, <E049><E003 6>My Lord.", "Permettez-moi de vous exprimer ma profonde gratitude pour votre\r\ncompréhension, <E049><E003 6>Votre Honneur.");
                R(ref s, "(But if this testimony holds...)", "(Mais si cette déposition tient debout...)");
                R(ref s, "(...Judge Jigoku will be deemed to have had <E006>no\r\ninvolvement<E007> in the case!)", "(...le juge Jigoku sera considéré comme n'ayant eu <E006>aucun\r\nrôle<E007> dans l'affaire !)");
                R(ref s, "Well, <E049><E003 6>Counsel?<E049><E003 10> <E025 2>I really see no reason for wasting precious\r\ncourt time here on a cross-examination.", "Eh bien, <E049><E003 6>Maître ?<E049><E003 10> <E025 2>Je ne vois vraiment pas l'intérêt d'un contre-interrogatoire\r\nqui gaspillerait le temps précieux de ce tribunal.");
                R(ref s, "Sorry, My Lord.<E049><E003 12> The defence has a right to\r\ncross-examine.<E049><E003 10> <E145 1 13><E118 1 1.3><E149 1 0 8><E003 10><E025 3>And I don't intend to squander that.", "Pardonnez-moi, Votre Honneur.<E049><E003 12> La défense est en droit de\r\ncontre-interroger le témoin.<E049><E003 10> <E145 1 13><E118 1 1.3><E149 1 0 8><E003 10><E025 3>Et je n'ai pas l'intention d'y renoncer.");
                R(ref s, "You're an embarrassment to your countrymen...<E049><E003 12>\r\n<E025 3>not knowing when you're beaten.", "Vous faites honte à vos compatriotes...<E049><E003 12>\r\n<E025 3>à refuser ainsi d'admettre votre défaite.");
                R(ref s, "In that case...<E049><E003 10><E025 2><E338><E341>proceed, <E049><E003 6>Mr Naruhodo!", "Dans ce cas...<E049><E003 10><E025 2><E338><E341>poursuivez, <E049><E003 6>M. Naruhodo !");
